59	static bool mem_has_vals(const uint8_t* p, size_t size, uint8_t val) {
60	  if (p==NULL) return false;
61	  for (size_t i = 0; i < size; ++i) {
62	    if (p[i] != val) return false;
63	  }
64	  return true;
65	}
66	static bool mem_is_zero(const void* p, size_t size) {
67	  return mem_has_vals((const uint8_t*)p,size,0);
68	}
