463	typedef enum mi_option_e {
464	  // stable options
465	  mi_option_show_errors,                // print error messages
466	  mi_option_show_stats,                 // print statistics on termination
467	  mi_option_verbose,                    // print verbose messages
468	  // advanced options
469	  mi_option_deprecated_eager_commit,    
470	  mi_option_arena_eager_commit,         // eager commit arenas? Use 2 to enable just on overcommit systems (=2)
471	  mi_option_purge_decommits,            // should a memory purge decommit? (=1). Set to 0 to use memory reset on a purge (instead of decommit)
472	  mi_option_allow_large_os_pages,       // allow use of large (2 or 4 MiB) OS pages, implies eager commit.
473	  mi_option_reserve_huge_os_pages,      // reserve N huge OS pages (1GiB pages) at startup
474	  mi_option_reserve_huge_os_pages_at,   // reserve huge OS pages at a specific NUMA node
475	  mi_option_reserve_os_memory,          // reserve specified amount of OS memory in an arena at startup (internally, this value is in KiB; use `mi_option_get_size`)
476	  mi_option_deprecated_segment_cache,
477	  mi_option_deprecated_page_reset,
478	  mi_option_deprecated_abandoned_page_purge,
479	  mi_option_deprecated_segment_reset,
480	  mi_option_deprecated_eager_commit_delay, 
481	  mi_option_purge_delay,                // memory purging is delayed by N milli seconds; use 0 for immediate purging or -1 for no purging at all. (=10)
482	  mi_option_use_numa_nodes,             // 0 = use all available numa nodes, otherwise use at most N nodes.
483	  mi_option_disallow_os_alloc,          // 1 = do not use OS memory for allocation (but only programmatically reserved arenas)
484	  mi_option_os_tag,                     // tag used for OS logging (macOS only for now) (=100)
485	  mi_option_max_errors,                 // issue at most N error messages
486	  mi_option_max_warnings,               // issue at most N warning messages
487	  mi_option_deprecated_max_segment_reclaim,  // max. percentage of the abandoned segments can be reclaimed per try (=10%)
488	  mi_option_destroy_on_exit,            // if set, release all memory on exit; sometimes used for dynamic unloading but can be unsafe
489	  mi_option_arena_reserve,              // initial memory size for arena reservation (= 1 GiB on 64-bit) (internally, this value is in KiB; use `mi_option_get_size`)
490	  mi_option_arena_purge_mult,           // multiplier for `purge_delay` for the purging delay for arenas (=10)
491	  mi_option_deprecated_purge_extend_delay,
492	  mi_option_disallow_arena_alloc,       // 1 = do not use arena's for allocation (except if using specific arena id's)
493	  mi_option_retry_on_oom,               // retry on out-of-memory for N milli seconds (=400), set to 0 to disable retries. (only on windows)
494	  mi_option_deprecated_visit_abandoned, // allow visiting theap blocks from abandoned threads (=0)
495	  mi_option_guarded_min,                // only used when building with MI_GUARDED: minimal rounded object size for guarded objects (=0)
496	  mi_option_guarded_max,                // only used when building with MI_GUARDED: maximal rounded object size for guarded objects (=0)
497	  mi_option_guarded_precise,            // disregard minimal alignment requirement to always place guarded blocks exactly in front of a guard page (=0)
498	  mi_option_guarded_sample_rate,        // 1 out of N allocations in the min/max range will be guarded (=1000)
499	  mi_option_guarded_sample_seed,        // can be set to allow for a (more) deterministic re-execution when a guard page is triggered (=0)
500	  mi_option_generic_collect,            // collect theaps every N (=10000) generic allocation calls
501	  mi_option_page_reclaim_on_free,       // reclaim abandoned pages on a free (=0). -1 disallowr always, 0 allows if the page originated from the current theap, 1 allow always
502	  mi_option_page_full_retain,           // retain N full (small) pages per size class (=2)
503	  mi_option_page_max_candidates,        // max candidate pages to consider for allocation (=4)
504	  mi_option_max_vabits,                 // max user space virtual address bits to consider (=48)
505	  mi_option_pagemap_commit,             // commit the full pagemap (to always catch invalid pointer uses) (=0)
506	  mi_option_page_commit_on_demand,      // commit page memory on-demand
507	  mi_option_page_max_reclaim,           // don't reclaim pages of the same originating theap if we already own N pages (in that size class) (=-1 (unlimited))
508	  mi_option_page_cross_thread_max_reclaim, // don't reclaim pages across threads if we already own N pages (in that size class) (=16)
509	  mi_option_allow_thp,                  // allow transparent huge pages? (=1) (on Android =0 by default). Set to 0 to disable THP for the process.
510	  mi_option_minimal_purge_size,         // set minimal purge size (in KiB) (=0). By default set to either 64 or 2048 if THP is enabled.
511	  mi_option_arena_max_object_size,      // set maximal object size that can be allocated in an arena (in KiB) (=2GiB on 64-bit). 
512	  mi_option_arena_is_numa_local,        // experimental
513	  _mi_option_last,
514	  // legacy option names
515	  mi_option_large_os_pages = mi_option_allow_large_os_pages,
516	  mi_option_eager_region_commit = mi_option_arena_eager_commit,
517	  mi_option_reset_decommits = mi_option_purge_decommits,
518	  mi_option_reset_delay = mi_option_purge_delay,
