556	mi_decl_nodiscard mi_decl_export void* mi_aligned_recalloc(void* p, size_t newcount, size_t size, size_t alignment) mi_attr_noexcept;
557	mi_decl_nodiscard mi_decl_export void* mi_aligned_offset_recalloc(void* p, size_t newcount, size_t size, size_t alignment, size_t offset) mi_attr_noexcept;
558	
559	mi_decl_export void mi_free_size_aligned(void* p, size_t size, size_t alignment) mi_attr_noexcept;
560	mi_decl_export void mi_free_aligned(void* p, size_t alignment)                   mi_attr_noexcept;
561	mi_decl_export int  mi_dupenv_s(char** buf, size_t* size, const char* name)      mi_attr_noexcept;
562	
563	// wide characters
564	mi_decl_export int mi_wdupenv_s(wchar_t** buf, size_t* size, const wchar_t* name)       mi_attr_noexcept;
565	mi_decl_nodiscard mi_decl_export mi_decl_restrict wchar_t* mi_wcsdup(const wchar_t* s)  mi_attr_noexcept mi_attr_malloc;
566	mi_decl_nodiscard mi_decl_export mi_decl_restrict unsigned char* mi_mbsdup(const unsigned char* s)  mi_attr_noexcept mi_attr_malloc;
567	
568	// The `mi_new` wrappers implement C++ semantics on out-of-memory instead of directly returning `NULL`.
569	// (and call `std::get_new_handler` and potentially raise a `std::bad_alloc` exception).
570	mi_decl_nodiscard mi_decl_export mi_decl_restrict void* mi_new(size_t size)                   mi_attr_malloc mi_attr_alloc_size(1);
571	mi_decl_nodiscard mi_decl_export mi_decl_restrict void* mi_new_aligned(size_t size, size_t alignment) mi_attr_malloc mi_attr_alloc_size(1) mi_attr_alloc_align(2);
572	mi_decl_nodiscard mi_decl_export mi_decl_restrict void* mi_new_nothrow(size_t size)           mi_attr_noexcept mi_attr_malloc mi_attr_alloc_size(1);
573	mi_decl_nodiscard mi_decl_export mi_decl_restrict void* mi_new_aligned_nothrow(size_t size, size_t alignment) mi_attr_noexcept mi_attr_malloc mi_attr_alloc_size(1) mi_attr_alloc_align(2);
574	mi_decl_nodiscard mi_decl_export mi_decl_restrict void* mi_new_n(size_t count, size_t size)   mi_attr_malloc mi_attr_alloc_size2(1, 2);
575	mi_decl_nodiscard mi_decl_export void* mi_new_realloc(void* p, size_t newsize)                mi_attr_alloc_size(2);
576	mi_decl_nodiscard mi_decl_export void* mi_new_reallocn(void* p, size_t newcount, size_t size) mi_attr_alloc_size2(2, 3);
577	
578	mi_decl_nodiscard mi_decl_export mi_decl_restrict void* mi_heap_alloc_new(mi_heap_t* heap, size_t size)                 mi_attr_malloc mi_attr_alloc_size(2);
579	mi_decl_nodiscard mi_decl_export mi_decl_restrict void* mi_heap_alloc_new_n(mi_heap_t* heap, size_t count, size_t size) mi_attr_malloc mi_attr_alloc_size2(2, 3);
580	
581	#ifdef __cplusplus
582	}
583	#endif
584	
585	// ---------------------------------------------------------------------------------------------
586	// Implement the C++ std::allocator interface for use in STL containers.
587	// (note: see `mimalloc-new-delete.h` for overriding the new/delete operators globally)
588	// ---------------------------------------------------------------------------------------------
589	#ifdef __cplusplus
590	
591	#include <cstddef>     // std::size_t
592	#include <cstdint>     // PTRDIFF_MAX
593	#if (__cplusplus >= 201103L) || (_MSC_VER > 1900)  // C++11
594	#include <type_traits> // std::true_type
595	#include <utility>     // std::forward
596	#endif
597	
598	template<class T> struct _mi_stl_allocator_common {
599	  typedef T                 value_type;
600	  typedef std::size_t       size_type;
601	  typedef std::ptrdiff_t    difference_type;
602	  typedef value_type&       reference;
603	  typedef value_type const& const_reference;
604	  typedef value_type*       pointer;
605	  typedef value_type const* const_pointer;
606	
607	  #if ((__cplusplus >= 201103L) || (_MSC_VER > 1900))  // C++11
608	  using propagate_on_container_copy_assignment = std::true_type;
609	  using propagate_on_container_move_assignment = std::true_type;
610	  using propagate_on_container_swap            = std::true_type;
611	  template <class U, class ...Args> void construct(U* p, Args&& ...args) { ::new(p) U(std::forward<Args>(args)...); }
612	  template <class U> void destroy(U* p) mi_attr_noexcept { p->~U(); }
613	  #else
614	  void construct(pointer p, value_type const& val) { ::new(p) value_type(val); }
615	  void destroy(pointer p) { p->~value_type(); }
616	  #endif
617	
618	  size_type     max_size() const mi_attr_noexcept { return (PTRDIFF_MAX/sizeof(value_type)); }
619	  pointer       address(reference x) const        { return &x; }
620	  const_pointer address(const_reference x) const  { return &x; }
621	};
622	
623	template<class T> struct mi_stl_allocator : public _mi_stl_allocator_common<T> {
624	  using typename _mi_stl_allocator_common<T>::size_type;
625	  using typename _mi_stl_allocator_common<T>::value_type;
626	  using typename _mi_stl_allocator_common<T>::pointer;
627	  template <class U> struct rebind { typedef mi_stl_allocator<U> other; };
628	
629	  mi_stl_allocator()                                             mi_attr_noexcept = default;
630	  mi_stl_allocator(const mi_stl_allocator&)                      mi_attr_noexcept = default;
631	  template<class U> mi_stl_allocator(const mi_stl_allocator<U>&) mi_attr_noexcept { }
632	  mi_stl_allocator  select_on_container_copy_construction() const { return *this; }
633	  void              deallocate(T* p, size_type) { mi_free(p); }
634	
635	  #if (__cplusplus >= 201703L)  // C++17
636	  mi_decl_nodiscard T* allocate(size_type count) { return static_cast<T*>(mi_new_n(count, sizeof(T))); }
637	  mi_decl_nodiscard T* allocate(size_type count, const void*) { return allocate(count); }
638	  #else
639	  mi_decl_nodiscard pointer allocate(size_type count, const void* = 0) { return static_cast<pointer>(mi_new_n(count, sizeof(value_type))); }
640	  #endif
641	
642	  #if ((__cplusplus >= 201103L) || (_MSC_VER > 1900))  // C++11
643	  using is_always_equal = std::true_type;
644	  #endif
645	};
646	
647	template<class T1,class T2> bool operator==(const mi_stl_allocator<T1>& , const mi_stl_allocator<T2>& ) mi_attr_noexcept { return true; }
648	template<class T1,class T2> bool operator!=(const mi_stl_allocator<T1>& , const mi_stl_allocator<T2>& ) mi_attr_noexcept { return false; }
649	
650	
651	#if (__cplusplus >= 201103L) || (_MSC_VER >= 1900)  // C++11
652	#define MI_HAS_HEAP_STL_ALLOCATOR 1
653	
654	#include <memory>      // std::shared_ptr
655	
656	// Common base class for STL allocators in a specific theap
657	template<class T, bool _mi_destroy> struct _mi_heap_stl_allocator_common : public _mi_stl_allocator_common<T> {
658	  using typename _mi_stl_allocator_common<T>::size_type;
659	  using typename _mi_stl_allocator_common<T>::value_type;
660	  using typename _mi_stl_allocator_common<T>::pointer;
661	
662	  _mi_heap_stl_allocator_common(mi_heap_t* hp) : heap(hp, [](mi_heap_t*) {}) {}    /* will not delete nor destroy the passed in heap */
663	
664	  #if (__cplusplus >= 201703L)  // C++17
665	  mi_decl_nodiscard T* allocate(size_type count) { return static_cast<T*>(mi_heap_alloc_new_n(this->heap.get(), count, sizeof(T))); }
666	  mi_decl_nodiscard T* allocate(size_type count, const void*) { return allocate(count); }
667	  #else
668	  mi_decl_nodiscard pointer allocate(size_type count, const void* = 0) { return static_cast<pointer>(mi_heap_alloc_new_n(this->heap.get(), count, sizeof(value_type))); }
669	  #endif
670	
671	  #if ((__cplusplus >= 201103L) || (_MSC_VER > 1900))  // C++11
672	  using is_always_equal = std::false_type;
673	  #endif
674	
675	  void collect(bool force) { mi_heap_collect(this->heap.get(), force); }
676	  template<class U> bool is_equal(const _mi_heap_stl_allocator_common<U, _mi_destroy>& x) const { return (this->heap == x.heap); }
677	
678	protected:
679	  std::shared_ptr<mi_heap_t> heap;
680	  template<class U, bool D> friend struct _mi_heap_stl_allocator_common;
681	
682	  _mi_heap_stl_allocator_common() {
683	    mi_heap_t* hp = mi_heap_new();
684	    this->heap.reset(hp, (_mi_destroy ? &heap_destroy : &heap_delete));  /* calls heap_delete/destroy when the refcount drops to zero */
685	  }
686	  _mi_heap_stl_allocator_common(const _mi_heap_stl_allocator_common& x) mi_attr_noexcept : heap(x.heap) { }
687	  template<class U> _mi_heap_stl_allocator_common(const _mi_heap_stl_allocator_common<U, _mi_destroy>& x) mi_attr_noexcept : heap(x.heap) { }
688	
689	private:
690	  static void heap_delete(mi_heap_t* hp)  { if (hp != NULL) { mi_heap_delete(hp); } }
691	  static void heap_destroy(mi_heap_t* hp) { if (hp != NULL) { mi_heap_destroy(hp); } }
692	};
693	
694	// STL allocator allocation in a specific heap
695	template<class T> struct mi_heap_stl_allocator : public _mi_heap_stl_allocator_common<T, false> {
696	  using typename _mi_heap_stl_allocator_common<T, false>::size_type;
697	  mi_heap_stl_allocator() : _mi_heap_stl_allocator_common<T, false>() { } // creates fresh heap that is deleted when the destructor is called
698	  mi_heap_stl_allocator(mi_heap_t* hp) : _mi_heap_stl_allocator_common<T, false>(hp) { }  // no delete nor destroy on the passed in heap
699	  template<class U> mi_heap_stl_allocator(const mi_heap_stl_allocator<U>& x) mi_attr_noexcept : _mi_heap_stl_allocator_common<T, false>(x) { }
700	
701	  mi_heap_stl_allocator select_on_container_copy_construction() const { return *this; }
702	  void deallocate(T* p, size_type) { mi_free(p); }
703	  template<class U> struct rebind { typedef mi_heap_stl_allocator<U> other; };
704	};
705	
706	template<class T1, class T2> bool operator==(const mi_heap_stl_allocator<T1>& x, const mi_heap_stl_allocator<T2>& y) mi_attr_noexcept { return (x.is_equal(y)); }
707	template<class T1, class T2> bool operator!=(const mi_heap_stl_allocator<T1>& x, const mi_heap_stl_allocator<T2>& y) mi_attr_noexcept { return (!x.is_equal(y)); }
708	
709	
710	// STL allocator allocation in a specific heap, where `free` does nothing and
711	// the heap is destroyed in one go on destruction -- use with care!
712	template<class T> struct mi_heap_destroy_stl_allocator : public _mi_heap_stl_allocator_common<T, true> {
713	  using typename _mi_heap_stl_allocator_common<T, true>::size_type;
714	  mi_heap_destroy_stl_allocator() : _mi_heap_stl_allocator_common<T, true>() { } // creates fresh heap that is destroyed when the destructor is called
715	  mi_heap_destroy_stl_allocator(mi_heap_t* hp) : _mi_heap_stl_allocator_common<T, true>(hp) { }  // no delete nor destroy on the passed in heap
716	  template<class U> mi_heap_destroy_stl_allocator(const mi_heap_destroy_stl_allocator<U>& x) mi_attr_noexcept : _mi_heap_stl_allocator_common<T, true>(x) { }
717	
718	  mi_heap_destroy_stl_allocator select_on_container_copy_construction() const { return *this; }
719	  void deallocate(T*, size_type) { /* do nothing as we destroy the heap on destruct. */ }
720	  template<class U> struct rebind { typedef mi_heap_destroy_stl_allocator<U> other; };
721	};
722	
723	template<class T1, class T2> bool operator==(const mi_heap_destroy_stl_allocator<T1>& x, const mi_heap_destroy_stl_allocator<T2>& y) mi_attr_noexcept { return (x.is_equal(y)); }
724	template<class T1, class T2> bool operator!=(const mi_heap_destroy_stl_allocator<T1>& x, const mi_heap_destroy_stl_allocator<T2>& y) mi_attr_noexcept { return (!x.is_equal(y)); }
725	
726	#endif // C++11
727	
728	#endif // __cplusplus
729	
730	#endif
